message GetPriceRequest {}

message GetPriceResponse {
  double price = 1;
}

message GetPriceHistoryRequest {
  int32 count = 1;
}

message GetPriceHistoryResponse {
  repeated PricePoint points = 1;
}

// A reasonably "fat" record so the JSON-vs-protobuf size/parse difference is real.
message PricePoint {
  int64 timestamp = 1;
  double price = 2;
  double low = 3;
  double high = 4;
  double average = 5;
  string currency = 6;
  string region = 7;
  string source = 8;
}

public override Task<GetPriceResponse> GetPrice(GetPriceRequest request, ServerCallContext context)
{
    var price = Random.Shared.Next(1, 998);
    return Task.FromResult(new GetPriceResponse { Price = price });
